APPEND_ONLY_TABLES = ("payment", "payment_allocation", "audit_log", "consent", "loan_adjustment", "cash_entry_history")


def _create_rules() -> None:
    # Append-only ledger and audit tables (PRD section 11): no UPDATE or DELETE, ever.
    op.execute(
        """
        CREATE FUNCTION lt_forbid_change() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN
          RAISE EXCEPTION 'append-only table %: % is not allowed', TG_TABLE_NAME, TG_OP
            USING ERRCODE = 'insufficient_privilege';
        END $$;
        """
    )
    for table in APPEND_ONLY_TABLES:
        op.execute(
            f"CREATE TRIGGER {table}_append_only BEFORE UPDATE OR DELETE ON {table} "
            f"FOR EACH ROW EXECUTE FUNCTION lt_forbid_change()"
        )
        op.execute(f"CREATE TRIGGER {table}_no_truncate BEFORE TRUNCATE ON {table} "
                   f"FOR EACH STATEMENT EXECUTE FUNCTION lt_forbid_change()")

    # Allocations of a payment sum to the payment amount (negated for a reversal).
    op.execute(
        """
        CREATE FUNCTION lt_check_allocation_sum() RETURNS trigger LANGUAGE plpgsql AS $$
        DECLARE expected bigint; actual bigint;
        BEGIN
          SELECT CASE WHEN p.kind = 'reversal' THEN -p.amount ELSE p.amount END INTO expected
            FROM payment p WHERE p.id = NEW.payment_id;
          SELECT COALESCE(SUM(penalty_part + interest_part + principal_part), 0) INTO actual
            FROM payment_allocation WHERE payment_id = NEW.payment_id;
          IF actual <> expected THEN
            RAISE EXCEPTION 'allocations of payment % sum to %, expected %', NEW.payment_id, actual, expected
              USING ERRCODE = 'check_violation';
          END IF;
          RETURN NULL;
        END $$;
        """
    )
    op.execute(
        "CREATE CONSTRAINT TRIGGER payment_allocation_sum AFTER INSERT ON payment_allocation "
        "DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION lt_check_allocation_sum()"
    )

    # Principal parts of a schedule sum to the loan principal.
    op.execute(
        """
        CREATE FUNCTION lt_check_schedule_sum() RETURNS trigger LANGUAGE plpgsql AS $$
        DECLARE expected bigint; actual bigint;
        BEGIN
          SELECT principal INTO expected FROM loan WHERE id = NEW.loan_id;
          SELECT COALESCE(SUM(principal_part), 0) INTO actual FROM schedule_item WHERE loan_id = NEW.loan_id;
          IF actual <> expected THEN
            RAISE EXCEPTION 'schedule of loan % sums to %, expected %', NEW.loan_id, actual, expected
              USING ERRCODE = 'check_violation';
          END IF;
          RETURN NULL;
        END $$;
        """
    )
    op.execute(
        "CREATE CONSTRAINT TRIGGER schedule_item_sum AFTER INSERT ON schedule_item "
        "DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION lt_check_schedule_sum()"
    )
    # Schedule rows are locked once saved: only the payment cache columns may change.
    op.execute(
        """
        CREATE FUNCTION lt_lock_schedule() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN
          IF TG_OP = 'DELETE' OR NEW.due_date <> OLD.due_date OR NEW.installment <> OLD.installment
             OR NEW.principal_part <> OLD.principal_part OR NEW.interest_part <> OLD.interest_part
             OR NEW.seq <> OLD.seq OR NEW.loan_id <> OLD.loan_id THEN
            RAISE EXCEPTION 'schedule rows are locked once the loan is saved'
              USING ERRCODE = 'insufficient_privilege';
          END IF;
          RETURN NEW;
        END $$;
        """
    )
    op.execute(
        "CREATE TRIGGER schedule_item_locked BEFORE UPDATE OR DELETE ON schedule_item "
        "FOR EACH ROW EXECUTE FUNCTION lt_lock_schedule()"
    )
    # Loan money terms cannot change after saving either.
    op.execute(
        """
        CREATE FUNCTION lt_lock_loan_terms() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN
          IF NEW.principal <> OLD.principal OR NEW.rate <> OLD.rate OR NEW.method <> OLD.method
             OR NEW.disbursal_date <> OLD.disbursal_date OR NEW.borrower_id <> OLD.borrower_id
             OR NEW.frequency <> OLD.frequency OR NEW.loan_no <> OLD.loan_no THEN
            RAISE EXCEPTION 'loan terms are locked once the loan is saved'
              USING ERRCODE = 'insufficient_privilege';
          END IF;
          RETURN NEW;
        END $$;
        """
    )
    op.execute(
        "CREATE TRIGGER loan_terms_locked BEFORE UPDATE ON loan FOR EACH ROW EXECUTE FUNCTION lt_lock_loan_terms()"
    )
    op.execute("CREATE TRIGGER loan_no_delete BEFORE DELETE ON loan FOR EACH ROW EXECUTE FUNCTION lt_forbid_change()")
    op.execute(
        "CREATE TRIGGER borrower_no_delete BEFORE DELETE ON borrower FOR EACH ROW EXECUTE FUNCTION lt_forbid_change()"
    )
    op.execute(
        "CREATE TRIGGER cash_entry_no_delete BEFORE DELETE ON cash_entry "
        "FOR EACH ROW EXECUTE FUNCTION lt_forbid_change()"
    )

    # The daily log (PRD section 7 and 11): a derived view over payments, loans and cash entries.
    # A reversal shows as negative money in on the day it was made (ADR-0003).
    op.execute(
        """
        CREATE VIEW daily_log AS
          SELECT p.paid_on AS entry_date, 'in'::text AS direction, 'payment'::text AS source_type,
                 p.id AS source_id, CASE WHEN p.kind = 'reversal' THEN -p.amount ELSE p.amount END AS amount,
                 p.mode::text AS mode, p.loan_id, p.created_at
            FROM payment p
          UNION ALL
          SELECT l.disbursal_date, 'out', 'loan', l.id, l.principal, l.disbursal_mode, l.id, l.created_at
            FROM loan l WHERE l.deleted_at IS NULL
          UNION ALL
          SELECT c.entry_date, c.direction, 'cash_entry', c.id, c.amount, c.mode, NULL, c.created_at
            FROM cash_entry c WHERE c.deleted_at IS NULL
        """
    )


